//div[@class='jianjie']/p/text()
<js>
var bookid = baseUrl.match(/novel\/(\d+)/)[1];
var cont = result;
var commentUrl = "https://xn--vcsx64d.als1010.space/index.php?s=/Home/comment/lists/id/" + bookid + "/type/novel/limit/5/size/12";
try {
    var src = java.ajax(commentUrl);
    var m = String(src).match(/var\s*trre=([\s\S]+?),page_num/);
    if (m) {
        var lists = JSON.parse(m[1]);
        cont += "\n\n🔻评论区（共" + lists.length + "条）：\n";
        if (lists.length > 0) {
            function formatTime(ts) {
                var d = new Date(ts);
                return d.getFullYear() + "-" + (d.getMonth()+1) + "-" + d.getDate();
            }
            function buildComments(comment, parentPath, level) {
                var floor = parentPath ? parentPath + "-" + comment.floorIndex : comment.floorIndex;
                var indent = "  ".repeat(level);
                var str = indent + (parentPath ? "│" : "") + "┌👤" + (comment.user ? comment.user.username : "已注销") + " (" + (comment.user ? comment.user.group : "") + ") " + formatTime(comment.create_time * 1000) + "\n";
                str += indent + (parentPath ? "│├" : "") + "评论：" + comment.content + "\n";
                str += "└─" + indent + "[" + floor + "楼]\n";
                if (comment._ && comment._.forEach) {
                    comment._.forEach(function(child, index) {
                        child.floorIndex = index + 1;
                        str += buildComments(child, floor, level + 1);
                    });
                }
                return str;
            }
            lists.forEach(function(c, i) {
                c.floorIndex = i + 1;
                cont += buildComments(c, "", 0);
            });
        } else {
            cont += "本书暂时没有评论\n";
        }
    }
} catch(e) {
    cont += "\n评论加载失败\n";
}
result = cont;
</js>

